import { getAST, getFileCategory, parseFrontmatter, replaceVariables } from '@mintlify/common';
import {
  categorizeMdxFiles,
  getErrorPosition,
  getMintIgnore,
  listContentFiles,
} from '@mintlify/prebuild';
import type { Root } from 'mdast';

import {
  applyEdits,
  collectAnchorLinks,
  parseContent,
  relocate,
  selectEdits,
  unmapEdit,
} from './mdx.js';
import { PARSE_ERROR } from './rules/parseError.js';
import type {
  Diagnostic,
  Edit,
  FileContext,
  FileFinding,
  FileKind,
  FileRule,
  Site,
  SiteFile,
} from './types.js';

const CHECKED_CATEGORIES = new Set<string | null>(['page', 'snippet', 'snippet-v2']);

export const readSiteFiles = async (baseDir: string): Promise<SiteFile[]> => {
  const { mdxCandidates: candidates } = await listContentFiles(
    baseDir,
    await getMintIgnore(baseDir)
  );
  const { snippets, snippetsV2 } = await categorizeMdxFiles(baseDir, candidates);
  const snippetFiles = new Set([...snippets, ...snippetsV2]);
  return candidates
    .filter((name) => /\.mdx?$/.test(name) && CHECKED_CATEGORIES.has(getFileCategory(name)))
    .map((name) => ({
      file: name.replace(/^\//, ''),
      kind: (snippetFiles.has(name) ? 'snippet' : 'page') as FileKind,
    }));
};

const readFrontmatter = (content: string): Record<string, unknown> => {
  try {
    const { attributes } = parseFrontmatter<unknown>(content);
    return attributes && typeof attributes === 'object' ? { ...attributes } : {};
  } catch {
    return {};
  }
};

type ParseError = { line?: number; column?: number; message: string };

const REASON_POSITION = /\s*\(\d+:\d+(?:-\d+:\d+)?\)$/;

export const toParseError = (error: unknown): ParseError => {
  const reason = (error as { reason?: unknown } | null)?.reason;
  const fallback = error instanceof Error ? error.message : 'could not parse this file';
  const text = typeof reason === 'string' ? reason : fallback;
  const position = error && typeof error === 'object' ? getErrorPosition(error) : null;
  return {
    ...(position?.line != null && { line: position.line }),
    ...(position?.column != null && { column: position.column }),
    message: text.replace(REASON_POSITION, ''),
  };
};

type Extras = Pick<FileContext, 'readFile' | 'anchorLinks'>;

const parseErrorDiagnostic = (file: string, error: ParseError): Diagnostic => ({
  ...error,
  rule: PARSE_ERROR.id,
  group: PARSE_ERROR.group,
  severity: PARSE_ERROR.severity,
  file,
  message: `${error.message} (other checks were skipped for this file)`,
});

type Parsed = { context: FileContext; approximate: boolean } | { error: ParseError };

const tryParseContent = (content: string): Root | undefined => {
  try {
    return parseContent(content);
  } catch {
    return undefined;
  }
};

export const parseFile = (
  file: string,
  content: string,
  baseDir: string,
  extras: Extras = {}
): Parsed => {
  const context = { file, content, baseDir, frontmatter: readFrontmatter(content), ...extras };
  const tree = tryParseContent(content);
  if (tree) return { context: { ...context, tree }, approximate: false };
  try {
    return { context: { ...context, tree: getAST(content, file) }, approximate: true };
  } catch (error) {
    return { error: toParseError(error) };
  }
};

const EMPTY_TREE = { type: 'root' as const, children: [] };

const SOURCE_STAGE = 1;
const AFTER_RAW_STAGE = 2;

type Stage = { content: string; edits: Edit[] };

const VARIABLE = /\{\{\s*([\w.\-]+)\s*\}\}/g;

const variableEdits = (content: string, variables: Record<string, string> = {}): Edit[] =>
  [...content.matchAll(VARIABLE)]
    .filter((match) => match[1] !== undefined && variables[match[1]] !== undefined)
    .map((match) => ({
      start: match.index,
      end: match.index + match[0].length,
      text: replaceVariables(match[0], variables),
    }));

const toDiagnostic = (
  rule: FileRule,
  file: string,
  { edit, ...finding }: FileFinding,
  stages: Stage[],
  stage: number
): Diagnostic => {
  const original = edit && unmapEdit(stages, stage, edit);
  return {
    ...finding,
    ...relocate(stages, stage, finding),
    rule: rule.id,
    group: rule.group,
    severity: rule.severity,
    file,
    ...(original && { fix: { file, ...original } }),
  };
};

const checkFile = (
  allRules: FileRule[],
  { file, kind }: SiteFile,
  content: string,
  baseDir: string,
  extras: Extras,
  variables?: Record<string, string>
): Diagnostic[] => {
  const rules = kind === 'snippet' ? allRules.filter((rule) => !rule.pagesOnly) : allRules;
  const raw = rules.filter((rule) => rule.raw);
  const treeRules = rules.filter((rule) => !rule.raw);
  const varEdits = kind === 'snippet' ? variableEdits(content, variables) : [];
  const source = applyEdits(content, varEdits);
  const rawContext = { file, content: source, baseDir, frontmatter: {}, tree: EMPTY_TREE };

  const rawFound = raw.flatMap((rule) =>
    rule.check(rawContext).map((finding) => ({ rule, finding }))
  );
  const rawEdits = selectEdits(
    rawFound.flatMap(({ finding }) => (finding.edit ? [finding.edit] : []))
  );
  const afterRaw = applyEdits(source, rawEdits);
  const stages: Stage[] = [
    { content, edits: varEdits },
    { content: source, edits: rawEdits },
    { content: afterRaw, edits: [] },
  ];
  const diagnostics = rawFound.map(({ rule, finding }) =>
    toDiagnostic(rule, file, finding, stages, SOURCE_STAGE)
  );

  const parsed = parseFile(file, afterRaw, baseDir, extras);
  if ('error' in parsed) {
    diagnostics.unshift(
      parseErrorDiagnostic(file, {
        ...parsed.error,
        ...relocate(stages, AFTER_RAW_STAGE, parsed.error),
      })
    );
    return diagnostics;
  }
  for (const rule of treeRules) {
    for (const finding of rule.check(parsed.context)) {
      const found = parsed.approximate ? { ...finding, edit: undefined } : finding;
      diagnostics.push(toDiagnostic(rule, file, found, stages, AFTER_RAW_STAGE));
    }
  }
  return diagnostics;
};

const collectSiteAnchorLinks = async (site: Site): Promise<ReadonlySet<string>> => {
  const pages = await Promise.all(
    site.files.map(({ file }) => collectAnchorLinks(file, site.read(file) ?? ''))
  );
  return new Set(pages.flat());
};

export const checkFiles = async (site: Site, rules: FileRule[]): Promise<Diagnostic[]> => {
  const anchorRules = new Set(rules.filter((rule) => rule.needsAnchorLinks).map(({ id }) => id));
  const targets = site.files.filter(({ file }) => !site.selected || site.selected.has(file));
  const checkTarget = (entry: SiteFile, extras: Extras) => {
    const content = site.read(entry.file);
    if (content === undefined) {
      return [parseErrorDiagnostic(entry.file, { message: 'could not read this file' })];
    }
    return checkFile(rules, entry, content, site.baseDir, extras, site.variables);
  };
  const needsLinks = (diagnostics: Diagnostic[]) =>
    diagnostics.some(({ rule }) => anchorRules.has(rule));
  const checked = targets.map((entry) => checkTarget(entry, { readFile: site.read }));
  if (!checked.some(needsLinks)) return checked.flat();
  const extras = { readFile: site.read, anchorLinks: await collectSiteAnchorLinks(site) };
  return targets.flatMap((entry, index) => {
    const diagnostics = checked[index] ?? [];
    return needsLinks(diagnostics) ? checkTarget(entry, extras) : diagnostics;
  });
};
